package cn.lan.overtime;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.io.IOException;
import java.util.*;

/** Owns all mutations; existing v1 records/settings tables and payloads stay intact. */
final class OvertimeStore {
 static final long RETENTION=30L*86400000;
 private final SQLiteDatabase db;
 OvertimeStore(SQLiteDatabase database){
  db=database;
  db.execSQL("CREATE TABLE IF NOT EXISTS records (id TEXT PRIMARY KEY, payload TEXT NOT NULL, start_ms INTEGER NOT NULL, end_ms INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS trash (id TEXT PRIMARY KEY, payload TEXT NOT NULL, deleted_at INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS templates (id TEXT PRIMARY KEY, payload TEXT NOT NULL)");
  db.execSQL("CREATE INDEX IF NOT EXISTS records_interval ON records(start_ms,end_ms)");
  db.execSQL("CREATE TABLE IF NOT EXISTS period_locks (id TEXT PRIMARY KEY,payload TEXT NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS recovery (id INTEGER PRIMARY KEY AUTOINCREMENT,payload TEXT NOT NULL,created_at INTEGER NOT NULL,reason TEXT NOT NULL)");
 }
 static long start(JSONObject r)throws Exception{return TimeMath.start(r.getString("date"),r.getString("start"));}
 static long end(JSONObject r)throws Exception{return TimeMath.end(r.getString("date"),r.getString("end"),r.getBoolean("nextDay"));}
 static JSONObject normalize(JSONObject r)throws Exception{
  String date=r.getString("date"),start=r.getString("start"),end=r.getString("end"),type=r.getString("type"),note=r.getString("note");
  if(!(r.get("nextDay") instanceof Boolean))throw new IllegalArgumentException("次日标记格式不正确");
  Object br=r.get("break");if(!(br instanceof Number)||((Number)br).doubleValue()!=((Number)br).intValue())throw new IllegalArgumentException("休息时长须为整数分钟");int rest=((Number)br).intValue();
  TimeMath.minutes(TimeMath.start(date,start),TimeMath.end(date,end,r.getBoolean("nextDay")),rest);
  if(!Arrays.asList("工作日","休息日","节假日").contains(type))throw new IllegalArgumentException("加班类型不正确");if(note.length()>500)throw new IllegalArgumentException("备注最多500个字");
  String id=r.optString("id","");if(id.isEmpty())id=UUID.randomUUID().toString();if(!id.matches("[a-zA-Z0-9-]{1,64}"))throw new IllegalArgumentException("记录编号不正确");
  JSONObject out=new JSONObject();out.put("id",id);out.put("date",date);out.put("start",start);out.put("end",end);out.put("nextDay",r.getBoolean("nextDay"));out.put("break",rest);out.put("type",type);out.put("note",note);return out;
 }
 private boolean contains(String table,String id){try(Cursor c=db.rawQuery("SELECT id FROM "+table+" WHERE id=?",new String[]{id})){return c.moveToFirst();}}
 private JSONObject get(String table,String id)throws Exception{try(Cursor c=db.rawQuery("SELECT payload FROM "+table+" WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("记录已不存在，请返回后重试");return new JSONObject(c.getString(0));}}
 private boolean overlaps(JSONObject r)throws Exception{try(Cursor c=db.rawQuery("SELECT id FROM records WHERE start_ms < ? AND end_ms > ? AND id != ? LIMIT 1",new String[]{""+end(r),""+start(r),r.getString("id")})){return c.moveToFirst();}}
 private void write(JSONObject r)throws Exception{ContentValues v=new ContentValues();v.put("id",r.getString("id"));v.put("payload",r.toString());v.put("start_ms",start(r));v.put("end_ms",end(r));if(db.insertWithOnConflict("records",null,v,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IOException("write failed");}
 synchronized JSONArray records()throws Exception{JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT payload FROM records ORDER BY start_ms DESC",null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}
 private void purge(){db.delete("trash","deleted_at<=?",new String[]{""+(System.currentTimeMillis()-RETENTION)});}
 synchronized JSONArray trash()throws Exception{purge();JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT payload,deleted_at FROM trash ORDER BY deleted_at DESC",null)){while(c.moveToNext()){JSONObject o=new JSONObject();o.put("record",new JSONObject(c.getString(0)));o.put("deletedAt",c.getLong(1));o.put("expiresAt",c.getLong(1)+RETENTION);a.put(o);}}return a;}
 synchronized JSONArray templates()throws Exception{JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT payload FROM templates ORDER BY rowid",null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}
 synchronized String getSetting(String key,String fallback){try(Cursor c=db.rawQuery("SELECT value FROM settings WHERE key=?",new String[]{key})){return c.moveToFirst()?c.getString(0):fallback;}}
 synchronized void setSetting(String key,String value)throws IOException{ContentValues v=new ContentValues();v.put("key",key);v.put("value",value);if(db.insertWithOnConflict("settings",null,v,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IOException("setting write failed");}
 synchronized JSONObject preferences()throws Exception{return validPreferences(new JSONObject(getSetting("preferences","{}")));}
 private JSONObject validPreferences(JSONObject p)throws Exception{
  String theme=p.optString("theme","system"),font=p.optString("font","system");
  if(!Arrays.asList("system","light","dark","soft").contains(theme)||!Arrays.asList("system","large").contains(font)||(p.has("animation")&&!(p.opt("animation") instanceof Boolean))||(p.has("split")&&!(p.opt("split") instanceof Boolean)))throw new IllegalArgumentException("error.preferences");
  int cycle=integer(p,"cycleDay",1),round=integer(p,"rounding",1);
  if(cycle<1||cycle>31||!Arrays.asList(1,5,15,30).contains(round))throw new IllegalArgumentException("v13.badRules");
  JSONObject out=new JSONObject();out.put("theme",theme);out.put("font",font);out.put("animation",p.optBoolean("animation",true));out.put("cycleDay",cycle);out.put("rounding",round);out.put("split",p.optBoolean("split",false));return out;
 }
 private static int integer(JSONObject p,String key,int fallback)throws Exception{if(!p.has(key))return fallback;Object n=p.get(key);if(!(n instanceof Number)||((Number)n).doubleValue()!=((Number)n).intValue())throw new IllegalArgumentException("v13.badRules");return ((Number)n).intValue();}
 synchronized void preferences(JSONObject p)throws Exception{JSONObject n=validPreferences(p),old=preferences();boolean changed=n.getInt("cycleDay")!=old.getInt("cycleDay")||n.getInt("rounding")!=old.getInt("rounding")||n.getBoolean("split")!=old.getBoolean("split");if(changed&&locks().length()>0)throw new IllegalArgumentException("v13.unlockRules");if(changed)snapshot("rules");setSetting("preferences",n.toString());}
 synchronized JSONObject state()throws Exception{JSONObject o=new JSONObject();o.put("records",records());o.put("trash",trash());o.put("templates",templates());o.put("preferences",preferences());o.put("lastBackup",getSetting("lastBackup",""));o.put("locks",locks());o.put("recovery",recoveries());o.put("reminder",new JSONObject(getSetting("reminder","{}")));return o;}
 synchronized JSONObject save(JSONObject input)throws Exception{String oldId=input.optString("id","");if(!oldId.isEmpty()&&!contains("records",oldId))throw new IllegalArgumentException("记录已不存在，请返回后重试");JSONObject r=normalize(input);if(!oldId.isEmpty())assertUnlocked(get("records",oldId));assertUnlocked(r);if(overlaps(r))throw new IllegalArgumentException("这段时间与已有记录重叠，请检查日期和时间");write(r);return r;}
 synchronized JSONArray batch(JSONArray list)throws Exception{
  if(list.length()<1||list.length()>62)throw new IllegalArgumentException("batch.datesError");JSONArray result=new JSONArray();db.beginTransaction();try{snapshot("batch");for(int i=0;i<list.length();i++){JSONObject row=list.getJSONObject(i),out=new JSONObject();out.put("date",row.optString("date"));try{row.put("id","");JSONObject r=normalize(row);assertUnlocked(r);if(overlaps(r))throw new IllegalArgumentException("这段时间与已有记录重叠，请检查日期和时间");write(r);out.put("ok",true);}catch(IllegalArgumentException|JSONException e){out.put("ok",false);out.put("message",e.getMessage());}result.put(out);}db.setTransactionSuccessful();}finally{db.endTransaction();}return result;
 }
 synchronized void delete(String id)throws Exception{JSONObject r=get("records",id);assertUnlocked(r);db.beginTransaction();try{ContentValues v=new ContentValues();v.put("id",id);v.put("payload",r.toString());v.put("deleted_at",System.currentTimeMillis());if(db.insertWithOnConflict("trash",null,v,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IOException();db.delete("records","id=?",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}}
 synchronized void restore(String id)throws Exception{purge();JSONObject r=normalize(get("trash",id));assertUnlocked(r);if(contains("records",id)||overlaps(r))throw new IllegalArgumentException("trash.conflict");db.beginTransaction();try{write(r);db.delete("trash","id=?",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}}
 synchronized void removeTrash(String id){if("*".equals(id))db.delete("trash",null,null);else db.delete("trash","id=?",new String[]{id});}
 private JSONObject normalizeTemplate(JSONObject input)throws Exception{String name=input.getString("name").trim(),id=input.optString("id","");if(name.isEmpty()||name.length()>80)throw new IllegalArgumentException("template.nameError");if(id.isEmpty())id=UUID.randomUUID().toString();if(!id.matches("[a-zA-Z0-9-]{1,64}"))throw new IllegalArgumentException("记录编号不正确");JSONObject source=new JSONObject(input.getJSONObject("record").toString());source.put("date","2000-01-01");source.put("id","");JSONObject out=new JSONObject();out.put("id",id);out.put("name",name);out.put("record",normalize(source));return out;}
 private void writeTemplate(JSONObject t)throws Exception{ContentValues v=new ContentValues();v.put("id",t.getString("id"));v.put("payload",t.toString());if(db.insertWithOnConflict("templates",null,v,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IOException();}
 synchronized void saveTemplate(JSONObject t)throws Exception{JSONObject n=normalizeTemplate(t);if(!contains("templates",n.getString("id"))&&templates().length()>=30)throw new IllegalArgumentException("template.limit");writeTemplate(n);}
 synchronized void deleteTemplate(String id){db.delete("templates","id=?",new String[]{id});}
 synchronized JSONObject backup()throws Exception{JSONObject b=new JSONObject();b.put("app","cn.lan.overtime");b.put("version",3);b.put("records",records());b.put("trash",trash());b.put("templates",templates());b.put("preferences",preferences());b.put("language",getSetting("language",""));b.put("locks",locks());b.put("reminder",new JSONObject(getSetting("reminder","{}")));return b;}
 JSONObject validateBackup(JSONObject b)throws Exception{
  if(!"cn.lan.overtime".equals(b.optString("app"))||!(b.opt("version") instanceof Number)||(b.getInt("version")<1||b.getInt("version")>3)||b.getDouble("version")!=b.getInt("version"))throw new IllegalArgumentException("请选择加班手记导出的原始备份文件");
  JSONArray a=b.getJSONArray("records");if(a.length()>10000)throw new IllegalArgumentException("单个备份最多10000条记录");JSONArray checked=new JSONArray();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(r.optString("id","").isEmpty())throw new IllegalArgumentException("备份缺少记录编号");checked.put(normalize(r));}
  JSONObject out=new JSONObject();out.put("records",checked);JSONArray ts=new JSONArray(),tr=new JSONArray();
  if(b.getInt("version")>=2){JSONArray input=b.getJSONArray("templates");if(input.length()>30)throw new IllegalArgumentException("template.limit");for(int i=0;i<input.length();i++)ts.put(normalizeTemplate(input.getJSONObject(i)));JSONArray trash=b.getJSONArray("trash");if(trash.length()>10000)throw new IllegalArgumentException("单个备份最多10000条记录");for(int i=0;i<trash.length();i++){JSONObject entry=trash.getJSONObject(i),record=entry.getJSONObject("record");if(record.optString("id","").isEmpty())throw new IllegalArgumentException("备份缺少记录编号");Object rawTime=entry.get("deletedAt");if(!(rawTime instanceof Number))throw new IllegalArgumentException("error.format");long time=((Number)rawTime).longValue();if(((Number)rawTime).doubleValue()!=time||time<0||time>System.currentTimeMillis()+300000)throw new IllegalArgumentException("error.format");JSONObject n=new JSONObject();n.put("record",normalize(record));n.put("deletedAt",time);tr.put(n);}}
  out.put("templates",ts);out.put("trash",tr);if(b.getInt("version")>=2){out.put("preferences",validPreferences(b.getJSONObject("preferences")));String lang=b.optString("language","");if(!lang.isEmpty()&&!Arrays.asList("zh","en").contains(lang))throw new IllegalArgumentException("error.format");out.put("language",lang);}if(b.getInt("version")==3){JSONArray ls=b.getJSONArray("locks");if(ls.length()>1212)throw new IllegalArgumentException("error.format");for(int i=0;i<ls.length();i++){JSONObject l=ls.getJSONObject(i);TimeMath.start(l.getString("from"),"00:00");TimeMath.start(l.getString("to"),"00:00");if(l.getString("from").compareTo(l.getString("to"))>0)throw new IllegalArgumentException("error.format");}out.put("locks",ls);out.put("reminder",validReminder(b.getJSONObject("reminder")));}return out;
 }
 private static final class Plan {JSONArray accepted=new JSONArray(),details=new JSONArray();int duplicates=0,conflicts=0,locked=0,replaced=0;}
 private Plan plan(JSONObject checked,String mode)throws Exception{
  if(!Arrays.asList("skip","replace","keep").contains(mode))throw new IllegalArgumentException("error.format");
  Plan p=new Plan();LinkedHashMap<String,JSONObject> working=new LinkedHashMap<>();JSONArray existing=records();for(int i=0;i<existing.length();i++){JSONObject r=existing.getJSONObject(i);working.put(r.getString("id"),r);}
  JSONArray a=checked.getJSONArray("records");Set<String> inputIds=new HashSet<>();
  for(int i=0;i<a.length();i++){
   JSONObject r=new JSONObject(a.getJSONObject(i).toString()),old=working.get(r.getString("id")),detail=new JSONObject();String id=r.getString("id"),status="added";
   if(!inputIds.add(id))throw new IllegalArgumentException("v13.duplicateIds");
   boolean identical=false;JSONObject without=new JSONObject(r.toString());without.remove("id");for(JSONObject other:working.values()){JSONObject cmp=new JSONObject(other.toString());cmp.remove("id");if(cmp.toString().equals(without.toString())){identical=true;break;}}
   if(identical||(old!=null&&"skip".equals(mode))||contains("trash",id)){p.duplicates++;status="duplicate";}
   else{
    if(old!=null&&"keep".equals(mode)){r.put("id",UUID.randomUUID().toString());old=null;}
    boolean conflict=false;for(JSONObject other:working.values()){if(old!=null&&other.getString("id").equals(old.getString("id")))continue;if(TimeMath.overlap(start(r),end(r),start(other),end(other))){conflict=true;break;}}
    if(conflict){p.conflicts++;status="conflict";}
    else if(isLocked(r)||(old!=null&&isLocked(old))){p.locked++;status="locked";}
    else{working.put(r.getString("id"),r);p.accepted.put(r);if(old!=null){p.replaced++;status="replaced";}}
   }
   detail.put("date",r.getString("date"));detail.put("start",r.getString("start"));detail.put("end",r.getString("end"));detail.put("status",status);p.details.put(detail);
  }return p;
 }
 synchronized JSONObject preview(JSONObject checked)throws Exception{return preview(checked,"skip");}
 synchronized JSONObject preview(JSONObject checked,String mode)throws Exception{Plan p=plan(checked,mode);JSONObject out=new JSONObject();out.put("added",p.accepted.length()-p.replaced);out.put("replaced",p.replaced);out.put("duplicates",p.duplicates);out.put("conflicts",p.conflicts);out.put("locked",p.locked);out.put("details",p.details);out.put("templates",checked.getJSONArray("templates").length());out.put("trash",checked.getJSONArray("trash").length());out.put("hasPreferences",checked.has("preferences"));return out;}
 synchronized JSONObject importBackup(JSONObject checked,boolean restoreSettings)throws Exception{return importBackup(checked,restoreSettings,"skip");}
 synchronized JSONObject importBackup(JSONObject checked,boolean restoreSettings,String mode)throws Exception{
  db.beginTransaction();try{snapshot("import");purge();Plan p=plan(checked,mode);for(int i=0;i<p.accepted.length();i++)write(p.accepted.getJSONObject(i));int templatesAdded=0,trashAdded=0;JSONArray ts=checked.getJSONArray("templates"),tr=checked.getJSONArray("trash");int templateCount=templates().length();for(int i=0;i<ts.length();i++){JSONObject t=ts.getJSONObject(i);if(!contains("templates",t.getString("id"))&&templateCount<30){writeTemplate(t);templateCount++;templatesAdded++;}}for(int i=0;i<tr.length();i++){JSONObject entry=tr.getJSONObject(i),r=entry.getJSONObject("record");String id=r.getString("id");long deletedAt=entry.getLong("deletedAt");if(deletedAt<=System.currentTimeMillis()-RETENTION||contains("records",id)||contains("trash",id))continue;ContentValues v=new ContentValues();v.put("id",id);v.put("payload",r.toString());v.put("deleted_at",deletedAt);if(db.insert("trash",null,v)==-1)throw new IOException();trashAdded++;}
  if(restoreSettings&&checked.has("preferences")){preferences(checked.getJSONObject("preferences"));String lang=checked.optString("language","");if(!lang.isEmpty())setSetting("language",lang);}
  // Backup locks describe an old snapshot; merged records must be checked again locally.
  JSONObject result=new JSONObject();result.put("added",p.accepted.length()-p.replaced);result.put("replaced",p.replaced);result.put("duplicates",p.duplicates);result.put("conflicts",p.conflicts);result.put("locked",p.locked);result.put("templatesAdded",templatesAdded);result.put("trashAdded",trashAdded);result.put("language",getSetting("language",""));db.setTransactionSuccessful();return result;}finally{db.endTransaction();}
 }
 synchronized JSONArray locks()throws Exception{JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT payload FROM period_locks ORDER BY id DESC",null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}
 private boolean touches(JSONObject r,String from,String to)throws Exception{String last=r.getString("date");if(preferences().getBoolean("split")&&r.getBoolean("nextDay")&&!"00:00".equals(r.getString("end")))last=java.time.LocalDate.parse(last).plusDays(1).toString();return r.getString("date").compareTo(to)<=0&&last.compareTo(from)>=0;}
 private boolean isLocked(JSONObject r)throws Exception{JSONArray a=locks();for(int i=0;i<a.length();i++){JSONObject l=a.getJSONObject(i);if(touches(r,l.getString("from"),l.getString("to")))return true;}return false;}
 private void assertUnlocked(JSONObject r)throws Exception{if(isLocked(r))throw new IllegalArgumentException("v13.lockedError");}
 synchronized JSONObject checkPeriod(String month)throws Exception{if(!month.matches("(20[0-9]{2}|2100)-(0[1-9]|1[0-2])"))throw new IllegalArgumentException("error.format");JSONObject pref=preferences();String[] b=Settlement.bounds(month,pref.getInt("cycleDay"));int total=0,count=0;JSONArray a=records();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);int[] n=Settlement.allocation(start(r),end(r),r.getInt("break"),pref.getInt("rounding"),pref.getBoolean("split"));String d=r.getString("date"),next=java.time.LocalDate.parse(d).plusDays(1).toString();boolean match=false;if(d.compareTo(b[0])>=0&&d.compareTo(b[1])<=0){total+=n[6];match=true;}if(n[1]>0&&next.compareTo(b[0])>=0&&next.compareTo(b[1])<=0){total+=n[7];match=true;}if(match)count++;}JSONObject o=new JSONObject();o.put("from",b[0]);o.put("to",b[1]);o.put("total",total);o.put("count",count);o.put("id",b[0]+"|"+b[1]);return o;}
 synchronized void lockPeriod(String month,boolean lock)throws Exception{JSONObject o=checkPeriod(month);if(lock){o.put("lockedAt",System.currentTimeMillis());ContentValues v=new ContentValues();v.put("id",o.getString("id"));v.put("payload",o.toString());if(db.insertWithOnConflict("period_locks",null,v,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IOException();}else db.delete("period_locks","id=?",new String[]{o.getString("id")});}
 synchronized void prepareUpgrade()throws Exception{if(!"1.3.0".equals(getSetting("snapshotVersion",""))){db.beginTransaction();try{snapshot("upgrade");setSetting("snapshotVersion","1.3.0");db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 private void snapshot(String reason)throws Exception{ContentValues v=new ContentValues();v.put("payload",backup().toString());v.put("created_at",System.currentTimeMillis());v.put("reason",reason);if(db.insertOrThrow("recovery",null,v)==-1)throw new IOException();db.execSQL("DELETE FROM recovery WHERE id NOT IN (SELECT id FROM recovery ORDER BY id DESC LIMIT 5)");}
 synchronized JSONArray recoveries()throws Exception{JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT id,created_at,reason FROM recovery ORDER BY id DESC",null)){while(c.moveToNext()){JSONObject o=new JSONObject();o.put("id",c.getLong(0));o.put("time",c.getLong(1));o.put("reason",c.getString(2));a.put(o);}}return a;}
 synchronized void recover(long id)throws Exception{JSONObject payload;try(Cursor c=db.rawQuery("SELECT payload FROM recovery WHERE id=?",new String[]{""+id})){if(!c.moveToFirst())throw new IllegalArgumentException("error.missingRecord");payload=validateBackup(new JSONObject(c.getString(0)));}
  db.beginTransaction();try{snapshot("recovery");db.delete("records",null,null);db.delete("trash",null,null);db.delete("templates",null,null);db.delete("period_locks",null,null);JSONArray a=payload.getJSONArray("records");Set<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(!ids.add(r.getString("id"))||overlaps(r))throw new IllegalArgumentException("error.format");write(r);}JSONArray ts=payload.getJSONArray("templates");for(int i=0;i<ts.length();i++)writeTemplate(ts.getJSONObject(i));JSONArray tr=payload.getJSONArray("trash");for(int i=0;i<tr.length();i++){JSONObject e=tr.getJSONObject(i),r=e.getJSONObject("record");ContentValues v=new ContentValues();v.put("id",r.getString("id"));v.put("payload",r.toString());v.put("deleted_at",e.getLong("deletedAt"));db.insertOrThrow("trash",null,v);}setSetting("preferences",payload.getJSONObject("preferences").toString());String lang=payload.optString("language","");if(!lang.isEmpty())setSetting("language",lang);JSONArray ls=payload.optJSONArray("locks");if(ls!=null)for(int i=0;i<ls.length();i++){JSONObject l=ls.getJSONObject(i);ContentValues v=new ContentValues();v.put("id",l.getString("from")+"|"+l.getString("to"));v.put("payload",l.toString());db.insertOrThrow("period_locks",null,v);}setSetting("reminder",payload.optJSONObject("reminder")==null?"{}":payload.getJSONObject("reminder").toString());db.setTransactionSuccessful();}finally{db.endTransaction();}
 }
 static JSONObject validReminder(JSONObject p)throws Exception{JSONObject o=new JSONObject();if(p.has("enabled")&&!(p.get("enabled") instanceof Boolean))throw new IllegalArgumentException("error.format");o.put("enabled",p.optBoolean("enabled",false));String time=p.optString("time","21:00");TimeMath.start("2026-01-01",time);o.put("time",time);JSONArray days=p.optJSONArray("days");if(days==null)days=new JSONArray("[1,2,3,4,5]");JSONArray checked=new JSONArray();Set<Integer> seen=new HashSet<>();for(int i=0;i<days.length();i++){Object d=days.get(i);if(!(d instanceof Number)||((Number)d).doubleValue()!=((Number)d).intValue()||((Number)d).intValue()<1||((Number)d).intValue()>7)throw new IllegalArgumentException("error.format");if(seen.add(((Number)d).intValue()))checked.put(d);}if(o.getBoolean("enabled")&&checked.length()==0)throw new IllegalArgumentException("v13.noDays");o.put("days",checked);return o;}
}
